namespace ks{namespace{SerialQueuePartialTest partialTest=nullptr;using T=SerialQueueTask;using S=T::Stage;using K=T::Kind;struct Point{unsigned location,length;};Point point(const T&t){switch(t.kind()){case K::ResetRx:switch(t.stage()){case S::RetainCritical:return{0xfe4,4};case S::MaskCritical:return{0xfe8,4};case S::RetainWord:return{0xfec,2};case S::Clear:return{0xfee,2};case S::WriteProducer:return{0xff0,6};case S::WriteConsumer:return{0xff6,6};case S::WriteStatus:return{0xffc,6};case S::RestoreWord:return{0x1002,2};case S::RestoreCritical:return{0x1004,4};case S::Finish:return{0x1008,2};default:break;}break;case K::PopRx:switch(t.stage()){case S::RetainFirst:return{0x100a,4};case S::RetainSecond:return{0x100e,4};case S::LocateStatus:return{0x1012,6};case S::RetainCritical:return{0x1018,4};case S::MaskCritical:return{0x101c,4};case S::ReadStatus:return{0x1020,2};case S::ClearData:return{0x1022,2};case S::WriteStatus:return{0x1024,2};case S::RestoreCritical:return{0x1026,4};case S::ReadConsumer:return{0x102a,6};case S::ReadProducer:return{0x1030,6};case S::CompareQueue:return{0x1036,2};case S::AdmitData:return{0x1038,2};case S::LocateData:return{0x103a,6};case S::Normalize:return{0x1040,2};case S::ResolveData:return{0x1042,2};case S::NextConsumer:return{0x1044,2};case S::MaskConsumer:return{0x1046,4};case S::WriteConsumer:return{0x104a,6};case S::ReadData:return{0x1050,2};case S::MarkData:return{0x1052,2};case S::RestoreSecond:return{0x1054,4};case S::RestoreFirst:return{0x1058,4};case S::Finish:return{0x105c,2};default:break;}break;case K::ResetTx:switch(t.stage()){case S::RetainCritical:return{0x10e4,4};case S::MaskCritical:return{0x10e8,4};case S::RetainWord:return{0x10ec,2};case S::Clear:return{0x10ee,2};case S::WriteProducer:return{0x10f0,6};case S::WriteConsumer:return{0x10f6,6};case S::RestoreWord:return{0x10fc,2};case S::RestoreCritical:return{0x10fe,4};case S::Finish:return{0x1102,2};default:break;}break;} throw std::runtime_error("Invalid serial queue stage");}}
bool SerialQueueCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0xfe4||pc==0x100a||pc==0x10e4){if(selected)throw std::runtime_error("Overlapping serial queue");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Serial queue capacity");selected->emplace(pc==0xfe4?K::ResetRx:pc==0x100a?K::PopRx:K::ResetTx,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto&v=h.regs;auto clock=[&]{auto at=t.dataAddress();return at>=0xfffd10?1u:3u;};auto cost=t.nextClocks(clock);bool tx=t.kind()==K::ResetTx;auto producer=tx?0xffed6cu:0xffec64u,consumer=tx?0xffed6eu:0xffec66u;t.advanceBefore(cost,[&](T::Read r)->uint32_t{switch(r){case T::Read::Status:return uint8_t(h.read8(0xffed68));case T::Read::Consumer:return uint16_t(h.read16(consumer));case T::Read::Producer:return uint16_t(h.read16(producer));case T::Read::Data:return uint8_t(h.read8(t.dataAddress()));}return 0;},[&](T::Write w,uint16_t value){if(w==T::Write::Status)f.store8(0xffed68,0);else f.store16(w==T::Write::Producer?producer:consumer,int16_t(value));},clock);auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::RetainCritical:v[7].er-=2;h.write16(h.exr,v[7].er);h.clockI(2);(**selected).depth+=2;break;case S::MaskCritical:h.exr=7;break;case S::RetainWord:hold(v[0].r);break;case S::Clear:v[0].r=h.sub16(v[0].r,v[0].r);break;case S::RestoreWord:restore(v[0].r);break;case S::RestoreCritical:h.exr=uint8_t(h.read16(v[7].er));v[7].er+=2;h.clockI(2);(**selected).depth-=2;break;case S::RetainFirst:hold(v[0].er);break;case S::RetainSecond:hold(v[1].er);break;case S::LocateStatus:f.move(v[0].er,0xffed68);break;case S::ReadStatus:f.move(v[6].rh,t.status());break;case S::ClearData:f.move(v[6].rl,0);break;case S::ReadConsumer:f.move(v[0].r,t.consumer());break;case S::ReadProducer:f.move(v[0].e,t.producer());break;case S::CompareQueue:h.sub16(v[0].r,v[0].e);break;case S::LocateData:f.move(v[1].er,0xffec68);break;case S::Normalize:v[0].er&=0xffff;value(h,v[0].er);break;case S::ResolveData:v[1].er=h.add32(v[1].er,v[0].er);break;case S::NextConsumer:f.inc(v[0].r,1);break;case S::MaskConsumer:v[0].r&=255;value(h,v[0].r);break;case S::ReadData:f.move(v[6].rl,t.data());break;case S::MarkData:v[6].rh|=1;value(h,v[6].rh);break;case S::RestoreSecond:restore(v[1].er);break;case S::RestoreFirst:restore(v[0].er);break;case S::Finish:if(t.kind()==K::PopRx&&uint16_t(v[6].r)!=t.result())throw std::runtime_error("Serial queue result differs");f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Serial queue clocks differ");return true;}}

